head.script:
(function () {
  const XHTML_NS = 'http://www.w3.org/1999/xhtml';
  const root = document.querySelector('foreignObject').firstElementChild;
  const createElementNS = document.createElementNS.bind(document);
  Object.defineProperty(document, 'head', { get: () => root.querySelector('head'), configurable: true });
  Object.defineProperty(document, 'body', { get: () => root.querySelector('body'), configurable: true });
  Object.defineProperty(document, 'documentElement', { get: () => root, configurable: true });
  document.createElement = function (tagName, options) { return createElementNS(XHTML_NS, tagName, options); };
})();

body.script:
const { ScramjetController } = $scramjetLoadController();
const scramjet = new ScramjetController({
  prefix: "/scramjet/",
  codec: { encode: (url) => encodeURIComponent(url), decode: (url) => decodeURIComponent(url) },
  flags: { captureErrors: true, strictRewrites: true }
});
let frame;
async function init() {
  const status = document.getElementById('status');
  try {
    if (!('serviceWorker' in navigator)) { status.textContent='need https'; return; }
    await navigator.serviceWorker.register('./sw.js', { scope: './' });
    await navigator.serviceWorker.ready;
    status.textContent='sw ready';
    await scramjet.init();
    status.textContent='ready';
    frame = scramjet.createFrame();
    document.getElementById('container').appendChild(frame.frame);
    frame.go('https://example.com');
  } catch(e){ console.error(e); status.textContent='error:'+e.message; }
}
document.getElementById('go').onclick = () => {
  const v=document.getElementById('url').value.trim();
  if(!v) return;
  frame.go(v.startsWith('http')?v:'https://'+v);
};
document.getElementById('url').onkeydown = e=>{ if(e.key==='Enter') document.getElementById('go').click(); };
init();
